test("neutral OS Vite artifact DATA matches neutral publication budgets and independent SQLite inventory",async()=>{
 const oracle=new Ajv({strict:true}),db=new Database(":memory:"),products=resolve(workspace,".fixture-products");
 try{
  for(const row of fixture.cases)expect(oracle.validate(schema,{version:1,mode:row.mode,renderer:row.renderer,command:row.command,engines:row.engines})).toBe(true);
  for(const row of fixture.invalid)expect(oracle.validate(schema,row)).toBe(false);
  expect(existsSync(producer),"actual OS domain request producer").toBe(true);
  const{frameworkOsViteArtifactInputsV1}=await import(pathToFileURL(producer).href)as{frameworkOsViteArtifactInputsV1:(products:string,value:unknown)=>readonly{path:string;owner:string;maximumBytes:number;maximumFiles:number}[]};
  db.exec("create table expected(path text primary key,owner text,bytes integer,files integer)");
  for(const row of fixture.cases){
   const request={version:1,mode:row.mode,renderer:row.renderer,command:row.command,engines:row.engines},actual=frameworkOsViteArtifactInputsV1(products,request),policy=publication.definitions.Protocol.const,font=fonts.definitions.Protocol.const;
   expect(actual).toHaveLength(row.count);expect(Object.isFrozen(actual)).toBe(true);db.exec("delete from expected");
   db.query("insert into expected values(?,?,?,?)").run(join(products,"infinite",row.mode,"fonts"),font.owner,font.maximumAssetBytes+font.maximumManifestBytes,font.maximumFiles);
   if(row.command==="build")db.query("insert into expected values(?,?,?,?)").run(join(products,"browser",row.mode,"flow"),"🧰️framework/🛍️products/💻️os/🔨️modules/🌊️flow/📦️packages/🦀️rust/Cargo.toml:flow-browser",policy.maximumOutputBytes+policy.maximumManifestBytes,policy.maximumFiles);
   if(row.engines!=="none"){const {frameworkOsEngineDeliveriesV1}=await import("../🕸️engines/🟦️.ts");for(const delivery of frameworkOsEngineDeliveriesV1(products,{version:1,mode:row.mode,facet:row.engines}))db.query("insert into expected values(?,?,?,?)").run(delivery.request.path,delivery.request.owner,delivery.request.maximumBytes,delivery.request.maximumFiles);}
   const trees=runtimeAssetStageTrees(products,row.mode).filter(tree=>tree.files.length);expect(trees.map(tree=>tree.files.length)).toEqual(fixture.canvasFiles);
   for(const tree of row.command==="build"?trees:[])db.query("insert into expected values(?,?,?,?)").run(tree.root,tree.owner,policy.maximumOutputBytes+policy.maximumManifestBytes,tree.files.length);
   const renderer=actual.find(input=>input.owner==="wgpu-renderer:"+row.mode);if(row.renderer==="wgpu"){expect(renderer).toBeDefined();expect(existsSync(join(workspace,fixture.rendererOwner,"Cargo.toml"))).toBe(true);expect(renderer!.path).toBe(join(products,"renderer",new Bun.CryptoHasher("sha256").update(fixture.rendererOwner).digest("hex").slice(0,20),row.mode,"wasm"));db.query("insert into expected values(?,?,?,?)").run(renderer!.path,renderer!.owner,policy.maximumOutputBytes+policy.maximumManifestBytes,policy.maximumFiles);}else expect(renderer).toBeUndefined();
   expect(actual.map(input=>({path:input.path,owner:input.owner,bytes:input.maximumBytes,files:input.maximumFiles})).sort((a,b)=>a.path.localeCompare(b.path,"en"))).toEqual((db.query("select * from expected").all()as{path:string;owner:string;bytes:number;files:number}[]).sort((a,b)=>a.path.localeCompare(b.path,"en")));
  }
  for(const row of fixture.invalid)expect(()=>frameworkOsViteArtifactInputsV1(products,row)).toThrow();
 }finally{db.close();}
});
